  # A small icon telling movies, series, books, and podcasts apart at a glance. Screen readers and
  # hover tooltips get the kind's name, unless it's `decorative` because the name is printed beside it.
  def kind_icon(title, decorative: false)
    label = title.kind.humanize
    paths = KIND_ICON_PATHS.fetch(title.kind).map { |d| tag.path(d: d) }
    accessibility = decorative ? { "aria-hidden": true } : { role: "img", "aria-label": label }

    tag.svg(safe_join([ (tag.title(label) unless decorative), *paths ].compact), xmlns: "http://www.w3.org/2000/svg",
      viewBox: "0 0 16 16", width: 16, height: 16, fill: "currentColor", class: "kind-icon kind-icon-#{title.kind}",
      **accessibility)
  end
end
